function u($s) { return json_decode('"' . $s . '"'); }
function w($name, $content) {
    global $view;
    $content = preg_replace_callback('/\\{\\{(.*?)\\}\\}/s', function ($m) { return u($m[1]); }, $content);
    file_put_contents($view . '/' . $name, $content);
}
