w('copy_fields.html', <<<'HTML'
<div class="panel panel-default" id="h5-copy-panel"><div class="panel-heading"><div class="panel-lead"><em>H5{{\u6587\u6848}}</em><span class="text-muted" style="font-size:12px;margin-left:8px;">{{\u7ba1\u7406 H5 \u9875\u9762\u5c55\u793a\u6587\u6848}}</span></div></div><div class="panel-body"><div class="form-group"><label class="control-label col-xs-12 col-sm-2">{{\u5feb\u901f\u7b5b\u9009}}:</label><div class="col-xs-12 col-sm-8"><input type="text" class="form-control" id="h5-copy-search" placeholder="{{\u6309\u952e\u540d\u3001\u6807\u7b7e\u6216\u6587\u6848\u7b5b\u9009}}"></div></div>{volist name="h5CopyAdminGroups" id="group"}<fieldset class="h5-copy-group" style="margin-bottom:18px;border:1px solid #e5e5e5;padding:12px 16px;border-radius:4px;"><legend class="h5-copy-group-title" style="width:auto;border:none;margin-bottom:10px;font-size:14px;font-weight:bold;cursor:pointer;"><i class="fa fa-chevron-down"></i> {$group.name}</legend><div class="h5-copy-group-body">{volist name="group.items" id="item"}<div class="form-group h5-copy-field" data-search="{$item.key} {$item.label}"><label class="control-label col-xs-12 col-sm-2">{$item.label}:</label><div class="col-xs-12 col-sm-8">{if condition="$item.is_long"}<textarea class="form-control" name="h5_copy[{$item.key}]" rows="3">{$item.value|htmlentities}</textarea>{else /}<input class="form-control" name="h5_copy[{$item.key}]" type="text" value="{$item.value|htmlentities}">{/if}<p class="help-block">{{\u952e\u540d}}: {$item.key}</p></div></div>{/volist}</div></fieldset>{/volist}<div class="form-group"><label class="control-label col-xs-12 col-sm-2"></label><div class="col-xs-12 col-sm-8"><button type="button" class="btn btn-warning" id="btn-reset-h5-copy"><i class="fa fa-undo"></i> {{\u6062\u590d\u9ed8\u8ba4\u6587\u6848}}</button></div></div></div></div>
<script>require(['jquery','fast'],function($,Fast){var $panel=$('#h5-copy-panel');$panel.on('click','.h5-copy-group-title',function(){$(this).closest('.h5-copy-group').find('.h5-copy-group-body').first().slideToggle(180);$(this).find('i.fa').toggleClass('fa-chevron-down fa-chevron-right');});$('#h5-copy-search').on('input',function(){var q=($(this).val()||'').toLowerCase().trim();$panel.find('.h5-copy-field').each(function(){var h=($(this).attr('data-search')||'').toLowerCase()+($(this).find('input,textarea').val()||'').toLowerCase();$(this).toggle(!q||h.indexOf(q)>=0);});$panel.find('.h5-copy-group').each(function(){$(this).toggle($(this).find('.h5-copy-field:visible').length>0);});});$('#btn-reset-h5-copy').on('click',function(){Layer.confirm('{{\u786e\u5b9a\u6062\u590d H5 \u9ed8\u8ba4\u6587\u6848\uff1f}}',{icon:3,title:'{{\u6062\u590d\u9ed8\u8ba4\u6587\u6848}}'},function(i){Layer.close(i);Fast.api.ajax({url:Fast.api.fixurl('fanshub.config/resetcopy'),type:'POST'},function(){location.reload();return false;});});});});</script>
HTML
);
w('i18n.html', <<<'HTML'
<div class="panel panel-default panel-intro"><div class="panel-heading"><div class="panel-lead"><em>{{\u591a\u8bed\u8a00}}</em><span class="text-muted" style="font-size:12px;margin-left:8px;">H5 {{\u6587\u6848\u591a\u8bed\u8a00\u5bf9\u7167\u7f16\u8f91}}</span></div></div><div class="panel-body">{include file="fanshub/config/_nav" /}<form id="i18n-form" class="form-horizontal" method="POST" action="{:url('fanshub.config/savei18n')}"><div class="form-group"><label class="control-label col-xs-12 col-sm-1">{{\u7b5b\u9009}}:</label><div class="col-xs-12 col-sm-6"><input type="text" class="form-control" id="i18n-search" placeholder="{{\u6309\u952e\u540d\u3001\u6807\u7b7e\u6216\u6587\u6848\u5185\u5bb9\u7b5b\u9009}}"></div><div class="col-xs-12 col-sm-5 text-right"><button type="submit" class="btn btn-primary">{{\u4fdd\u5b58\u5168\u90e8\u8bed\u8a00}}</button></div></div><div class="table-responsive"><table class="table table-bordered" id="i18n-table"><thead><tr><th>{{\u952e\u540d}} / {{\u6807\u7b7e}}</th>{foreach name="i18nLocales" item="locLabel" key="locCode"}<th>{$locLabel|htmlentities}<br><small>{$locCode}</small></th>{/foreach}</tr></thead><tbody>{volist name="i18nGroups" id="group"}<tr class="i18n-group-row"><td colspan="7">{$group.name|htmlentities}</td></tr>{volist name="group.items" id="item"}<tr class="i18n-data-row" data-search="{$item.key} {$item.label}"><td>{$item.label|htmlentities}<br><code>{$item.key}</code></td>{volist name="item.cells" id="cell"}<td>{if condition="$item.is_long || $item.is_html"}<textarea class="form-control i18n-cell" name="i18n[{$cell.code}][{$item.key}]">{$cell.value|htmlentities}</textarea>{else /}<input class="form-control i18n-cell" name="i18n[{$cell.code}][{$item.key}]" value="{$cell.value|htmlentities}">{/if}</td>{/volist}</tr>{/volist}{/volist}</tbody></table></div><div class="text-center"><button type="submit" class="btn btn-primary btn-embossed">{{\u4fdd\u5b58\u5168\u90e8\u8bed\u8a00}}</button></div></form></div></div>
HTML
);
w('production_checklist.html', <<<'HTML'
<div class="panel panel-{$productionChecklist.level|default='warning'} panel-intro" id="production-checklist-panel"><div class="panel-heading"><div class="panel-lead"><em>{{\u751f\u4ea7\u914d\u7f6e\u68c0\u67e5}}</em><span class="text-muted" style="font-size:12px;margin-left:8px;">{$productionChecklist.summary|default=''|htmlentities}</span></div><div class="panel-actions"><a href="javascript:;" class="btn btn-xs btn-default" id="btn-refresh-checklist"><i class="fa fa-refresh"></i> {{\u5237\u65b0}}</a></div></div><div class="panel-body"><div class="row"><div class="col-sm-4"><span class="label label-success">{{\u901a\u8fc7}} {$productionChecklist.counts.ok|default=0}</span></div><div class="col-sm-4"><span class="label label-warning">{{\u5efa\u8bae}} {$productionChecklist.counts.warn|default=0}</span></div><div class="col-sm-4"><span class="label label-danger">{{\u5fc5\u987b\u4fee\u590d}} {$productionChecklist.counts.fail|default=0}</span></div></div><table class="table table-bordered"><thead><tr><th>{{\u72b6\u6001}}</th><th>{{\u68c0\u67e5\u9879}}</th><th>{{\u8bf4\u660e}}</th></tr></thead><tbody id="production-checklist-body">{volist name="productionChecklist.items" id="item"}<tr data-field="{$item.field|default=''|htmlentities}"><td>{switch name="item.status"}{case value="ok"}<span class="label label-success">{{\u901a\u8fc7}}</span>{/case}{case value="warn"}<span class="label label-warning">{{\u5efa\u8bae}}</span>{/case}{case value="fail"}<span class="label label-danger">{{\u5fc5\u987b\u4fee\u590d}}</span>{/case}{default /}<span class="label label-default">{{\u72b6\u6001}}</span>{/switch}</td><td>{$item.title|htmlentities}</td><td>{$item.message|htmlentities}</td></tr>{/volist}</tbody></table></div></div>
HTML
);
